    32→// ListCheckpoints returns all checkpoints from the entire/sessions branch.
    33→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
    34→// Used by both manual-commit and auto-commit strategies.
    35→func ListCheckpoints() ([]CheckpointInfo, error) {
    36→	repo, err := OpenRepository()
    37→	if err != nil {
    38→		return nil, fmt.Errorf("failed to open git repository: %w", err)
    39→	}
    40→
    41→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    42→	ref, err := repo.Reference(refName, true)
    43→	if err != nil {
    44→		//nolint:nilerr // No sessions branch yet is expected, return empty list
    45→		return []CheckpointInfo{}, nil
    46→	}
    47→
    48→	commit, err := repo.CommitObject(ref.Hash())
    49→	if err != nil {
    50→		return nil, fmt.Errorf("failed to get commit object: %w", err)
    51→	}
    52→
    53→	tree, err := commit.Tree()
    54→	if err != nil {
    55→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
    56→	}
    57→
    58→	var checkpoints []CheckpointInfo
    59→
    60→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
    61→	// The tree has 2-character directories (hex buckets)
    62→	for _, bucketEntry := range tree.Entries {
    63→		if bucketEntry.Mode != filemode.Dir {
    64→			continue
    65→		}
    66→		// Bucket should be 2 hex chars
    67→		if len(bucketEntry.Name) != 2 {
    68→			continue
    69→		}
    70→
    71→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
    72→		if treeErr != nil {
    73→			continue
    74→		}
    75→
    76→		// Each entry in the bucket is the remaining part of the checkpoint ID
    77→		for _, checkpointEntry := range bucketTree.Entries {
    78→			if checkpointEntry.Mode != filemode.Dir {
    79→				continue
    80→			}
    81→
    82→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
    83→			if cpTreeErr != nil {
    84→				continue
    85→			}
    86→
    87→			// Reconstruct checkpoint ID: <bucket><remaining>
    88→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
    89→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
    90→			if cpErr != nil {
    91→				// Skip invalid checkpoint IDs
    92→				continue
    93→			}
    94→
    95→			info := CheckpointInfo{
    96→				CheckpointID: checkpointID,
    97→			}
    98→
    99→			// Get details from metadata file
   100→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   101→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   102→					//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   103→					json.Unmarshal([]byte(content), &info)
   104→				}
   105→			}
   106→
   107→			checkpoints = append(checkpoints, info)
   108→		}
   109→	}
   110→
   111→	// Sort by time (most recent first)
   112→	sort.Slice(checkpoints, func(i, j int) bool {
   113→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   114→	})
   115→
   116→	return checkpoints, nil
   117→}
