   130→// ensureMetadataBranch creates the orphan entire/sessions branch if it doesn't exist.
   131→// This branch has no parent and starts with an empty tree.
   132→func EnsureMetadataBranch(repo *git.Repository) error {
   133→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   134→
   135→	// Check if branch already exists
   136→	_, err := repo.Reference(refName, true)
   137→	if err == nil {
   138→		// Branch already exists
   139→		return nil
   140→	}
   141→
   142→	// Create empty tree (no files)
   143→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
   144→	obj := repo.Storer.NewEncodedObject()
   145→	if err := emptyTree.Encode(obj); err != nil {
   146→		return fmt.Errorf("failed to encode empty tree: %w", err)
   147→	}
   148→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
   149→	if err != nil {
   150→		return fmt.Errorf("failed to store empty tree: %w", err)
   151→	}
   152→
   153→	// Create orphan commit (no parent)
   154→	now := time.Now()
   155→	sig := object.Signature{
   156→		Name:  "Entire",
   157→		Email: "entire@local",
   158→		When:  now,
   159→	}
   160→
   161→	commit := &object.Commit{
   162→		TreeHash:  emptyTreeHash,
   163→		Author:    sig,
   164→		Committer: sig,
   165→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata for the auto-commit strategy.\n",
   166→	}
   167→	// Note: No ParentHashes - this is an orphan commit
   168→
   169→	commitObj := repo.Storer.NewEncodedObject()
   170→	if err := commit.Encode(commitObj); err != nil {
   171→		return fmt.Errorf("failed to encode orphan commit: %w", err)
   172→	}
   173→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   174→	if err != nil {
   175→		return fmt.Errorf("failed to store orphan commit: %w", err)
   176→	}
   177→
   178→	// Create branch reference
   179→	ref := plumbing.NewHashReference(refName, commitHash)
   180→	if err := repo.Storer.SetReference(ref); err != nil {
   181→		return fmt.Errorf("failed to create metadata branch: %w", err)
   182→	}
   183→
   184→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
   185→	return nil
   186→}
