   229→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
   230→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
   231→// Returns empty string if no valid prompt is found.
   232→func ExtractFirstPrompt(content string) string {
   233→	if content == "" {
   234→		return ""
   235→	}
   236→
   237→	// Prompts are separated by "\n\n---\n\n"
   238→	// Find the first non-empty prompt
   239→	prompts := strings.Split(content, "\n\n---\n\n")
   240→	var firstPrompt string
   241→	for _, p := range prompts {
   242→		cleaned := strings.TrimSpace(p)
   243→		// Skip empty prompts or prompts that are just dashes/separators
   244→		if cleaned == "" || isOnlySeparators(cleaned) {
   245→			continue
   246→		}
   247→		firstPrompt = cleaned
   248→		break
   249→	}
   250→
   251→	if firstPrompt == "" {
   252→		return ""
   253→	}
   254→
   255→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
   256→}
