   275→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
   276→func isOnlySeparators(s string) bool {
   277→	for _, r := range s {
   278→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
   279→			return false
   280→		}
   281→	}
   282→	return true
   283→}
