   285→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
   286→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
   287→// For single-session checkpoints, returns a slice with just the root prompt.
   288→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
   289→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
   290→		// Single session - just return the root prompt
   291→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
   292→		if prompt != "" {
   293→			return []string{prompt}
   294→		}
   295→		return nil
   296→	}
   297→
   298→	// Multi-session: read prompts from archived folders (1/, 2/, etc.) and root
   299→	prompts := make([]string, len(sessionIDs))
   300→
   301→	// Read archived session prompts (folders 1, 2, ... N-1)
   302→	for i := 1; i < sessionCount; i++ {
   303→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
   304→		prompts[i-1] = ReadSessionPromptFromTree(tree, archivedPath)
   305→	}
   306→
   307→	// Read the most recent session prompt (at root level)
   308→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
   309→
   310→	return prompts
   311→}
