   313→// ReadSessionPromptFromShadow reads the first prompt for a session from the shadow branch.
   314→// Returns an empty string if the prompt cannot be read.
   315→func ReadSessionPromptFromShadow(repo *git.Repository, baseCommit, sessionID string) string {
   316→	// Get shadow branch for this base commit (try full hash first, then shortened)
   317→	shadowBranchName := shadowBranchPrefix + baseCommit
   318→	ref, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true)
   319→	if err != nil {
   320→		// Try shortened hash (7 chars)
   321→		if len(baseCommit) > 7 {
   322→			shadowBranchName = shadowBranchPrefix + baseCommit[:7]
   323→			ref, err = repo.Reference(plumbing.NewBranchReferenceName(shadowBranchName), true)
   324→			if err != nil {
   325→				return ""
   326→			}
   327→		} else {
   328→			return ""
   329→		}
   330→	}
   331→
   332→	commit, err := repo.CommitObject(ref.Hash())
   333→	if err != nil {
   334→		return ""
   335→	}
   336→
   337→	tree, err := commit.Tree()
   338→	if err != nil {
   339→		return ""
   340→	}
   341→
   342→	// Build the path to prompt.txt: .entire/metadata/<session-id>/prompt.txt
   343→	checkpointPath := paths.EntireMetadataDir + "/" + sessionID
   344→	return ReadSessionPromptFromTree(tree, checkpointPath)
   345→}
