   367→// OpenRepository opens the git repository with linked worktree support enabled.
   368→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
   369→// which is required for proper operation in git worktrees created via 'git worktree add'.
   370→//
   371→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
   372→// - Commits appear to succeed but are not persisted
   373→// - Refs are written to incorrect locations
   374→// - The worktree's HEAD/index don't get updated properly
   375→//
   376→// This happens because worktrees use .git as a file (pointing to the main repo)
   377→// rather than a directory, and go-git needs to route paths correctly between
   378→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
   379→//
   380→// The function first uses 'git rev-parse --show-toplevel' to find the repository
   381→// root, which works correctly even when called from a subdirectory within the repo.
   382→func OpenRepository() (*git.Repository, error) {
   383→	// First, find the repository root using git rev-parse --show-toplevel
   384→	// This works correctly from any subdirectory within the repository
   385→	repoRoot, err := GetWorktreePath()
   386→	if err != nil {
   387→		// Fallback to current directory if git command fails
   388→		// (e.g., if git is not installed or we're not in a repo)
   389→		repoRoot = "."
   390→	}
   391→
   392→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
   393→		EnableDotGitCommonDir: true,
   394→	})
   395→	if err != nil {
   396→		return nil, fmt.Errorf("failed to open repository: %w", err)
   397→	}
   398→	return repo, nil
   399→}
