   401→// IsInsideWorktree returns true if the current directory is inside a git worktree
   402→// (as opposed to the main repository). Worktrees have .git as a file pointing
   403→// to the main repo, while the main repo has .git as a directory.
   404→// This function works correctly from any subdirectory within the repository.
   405→func IsInsideWorktree() bool {
   406→	// First find the repository root
   407→	repoRoot, err := GetWorktreePath()
   408→	if err != nil {
   409→		return false
   410→	}
   411→
   412→	gitPath := filepath.Join(repoRoot, gitDir)
   413→	gitInfo, err := os.Stat(gitPath)
   414→	if err != nil {
   415→		return false
   416→	}
   417→	return !gitInfo.IsDir()
   418→}
   419→
   420→// GetMainRepoRoot returns the root directory of the main repository.
   421→// In the main repo, this is the worktree path (repo root).
   422→// In a worktree, this parses the .git file to find the main repo.
   423→// This function works correctly from any subdirectory within the repository.
   424→//
   425→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
   426→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
   427→// See: https://git-scm.com/docs/gitrepository-layout
   428→func GetMainRepoRoot() (string, error) {
   429→	// First find the worktree/repo root
   430→	repoRoot, err := GetWorktreePath()
   431→	if err != nil {
   432→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   433→	}
   434→
   435→	if !IsInsideWorktree() {
   436→		return repoRoot, nil
   437→	}
   438→
   439→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
   440→	gitFilePath := filepath.Join(repoRoot, gitDir)
   441→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
   442→	if err != nil {
   443→		return "", fmt.Errorf("failed to read .git file: %w", err)
   444→	}
   445→
   446→	gitdir := strings.TrimSpace(string(content))
   447→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
   448→
   449→	// Extract main repo root: everything before "/.git/"
   450→	idx := strings.LastIndex(gitdir, "/.git/")
   451→	if idx < 0 {
   452→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
   453→	}
   454→	return gitdir[:idx], nil
   455→}
   456→
   457→// GetGitCommonDir returns the path to the shared git directory.
   458→// In a regular checkout, this is .git/
   459→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   460→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
   461→func GetGitCommonDir() (string, error) {
   462→	ctx := context.Background()
   463→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   464→	cmd.Dir = "."
   465→	output, err := cmd.Output()
   466→	if err != nil {
   467→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   468→	}
   469→
   470→	commonDir := strings.TrimSpace(string(output))
   471→
   472→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   473→	// so we need to make it absolute if it isn't already
   474→	if !filepath.IsAbs(commonDir) {
   475→		commonDir = filepath.Join(".", commonDir)
   476→	}
   477→
   478→	return filepath.Clean(commonDir), nil
   479→}
