   481→// GetWorktreePath returns the absolute path to the current worktree root.
   482→// This is the working directory path, not the git directory.
   483→func GetWorktreePath() (string, error) {
   484→	ctx := context.Background()
   485→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
   486→	output, err := cmd.Output()
   487→	if err != nil {
   488→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   489→	}
   490→	return strings.TrimSpace(string(output)), nil
   491→}
