   493→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
   494→// Works correctly from any subdirectory within the repository.
   495→func EnsureEntireGitignore() error {
   496→	// Get absolute path for the gitignore file
   497→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
   498→	if err != nil {
   499→		gitignoreAbs = entireGitignore // Fallback to relative
   500→	}
   501→
   502→	// Read existing content
   503→	var content string
   504→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
   505→		content = string(data)
   506→	}
   507→
   508→	// All entries that should be in .entire/.gitignore
   509→	requiredEntries := []string{
   510→		"tmp/",
   511→		"settings.local.json",
   512→		"metadata/",
   513→		"current_session",
   514→		"logs/",
   515→	}
   516→
   517→	// Track what needs to be added
   518→	var toAdd []string
   519→	for _, entry := range requiredEntries {
   520→		if !strings.Contains(content, entry) {
   521→			toAdd = append(toAdd, entry)
   522→		}
   523→	}
   524→
   525→	// Nothing to add
   526→	if len(toAdd) == 0 {
   527→		return nil
   528→	}
   529→
   530→	// Ensure .entire directory exists
   531→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
   532→		return fmt.Errorf("failed to create .entire directory: %w", err)
   533→	}
   534→
   535→	// Append missing entries to gitignore
   536→	var sb strings.Builder
   537→	for _, entry := range toAdd {
   538→		sb.WriteString(entry + "\n")
   539→	}
   540→	content += sb.String()
   541→
   542→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
   543→		return fmt.Errorf("failed to write gitignore: %w", err)
   544→	}
   545→	return nil
   546→}
