   548→// checkCanRewind checks if working directory is clean enough for rewind.
   549→// Returns (canRewind, reason, error). Shared by shadow and linear-shadow strategies.
   550→func checkCanRewind() (bool, string, error) {
   551→	repo, err := OpenRepository()
   552→	if err != nil {
   553→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
   554→	}
   555→
   556→	worktree, err := repo.Worktree()
   557→	if err != nil {
   558→		return false, "", fmt.Errorf("failed to get worktree: %w", err)
   559→	}
   560→
   561→	status, err := worktree.Status()
   562→	if err != nil {
   563→		return false, "", fmt.Errorf("failed to get status: %w", err)
   564→	}
   565→
   566→	if status.IsClean() {
   567→		return true, "", nil
   568→	}
   569→
   570→	var modified, added, deleted []string
   571→	for file, st := range status {
   572→		// Skip .entire directory
   573→		if paths.IsInfrastructurePath(file) {
   574→			continue
   575→		}
   576→
   577→		// Skip untracked files
   578→		if st.Worktree == git.Untracked {
   579→			continue
   580→		}
   581→
   582→		switch {
   583→		case st.Staging == git.Added || st.Worktree == git.Added:
   584→			added = append(added, file)
   585→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   586→			deleted = append(deleted, file)
   587→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   588→			modified = append(modified, file)
   589→		}
   590→	}
   591→
   592→	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
   593→		return true, "", nil
   594→	}
   595→
   596→	var msg strings.Builder
   597→	msg.WriteString("You have uncommitted changes:\n")
   598→	for _, f := range modified {
   599→		msg.WriteString(fmt.Sprintf("  modified:   %s\n", f))
   600→	}
   601→	for _, f := range added {
   602→		msg.WriteString(fmt.Sprintf("  added:      %s\n", f))
   603→	}
   604→	for _, f := range deleted {
   605→		msg.WriteString(fmt.Sprintf("  deleted:    %s\n", f))
   606→	}
   607→	msg.WriteString("\nPlease commit or stash your changes before rewinding.")
   608→
   609→	return false, msg.String(), nil
   610→}
   611→
   612→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
   613→// Unlike checkCanRewind, this always returns canRewind=true but includes a warning message
   614→// with +/- line stats for uncommitted changes. Used by manual-commit strategy.
   615→func checkCanRewindWithWarning() (bool, string, error) {
   616→	repo, err := OpenRepository()
   617→	if err != nil {
   618→		// Can't open repo - still allow rewind but without stats
   619→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
   620→	}
   621→
   622→	worktree, err := repo.Worktree()
   623→	if err != nil {
   624→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
   625→	}
   626→
   627→	status, err := worktree.Status()
   628→	if err != nil {
   629→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
   630→	}
   631→
   632→	if status.IsClean() {
   633→		return true, "", nil
   634→	}
   635→
   636→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
   637→	head, err := repo.Head()
   638→	if err != nil {
   639→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
   640→	}
   641→
   642→	headCommit, err := repo.CommitObject(head.Hash())
   643→	if err != nil {
   644→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
   645→	}
   646→
   647→	headTree, err := headCommit.Tree()
   648→	if err != nil {
   649→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
   650→	}
   651→
   652→	type fileChange struct {
   653→		status   string // "modified", "added", "deleted"
   654→		added    int
   655→		removed  int
   656→		filename string
   657→	}
   658→
   659→	var changes []fileChange
   660→	// Use repo root, not cwd - git status returns paths relative to repo root
   661→	repoRoot, err := GetWorktreePath()
   662→	if err != nil {
   663→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo root lookup fails
   664→	}
   665→
   666→	for file, st := range status {
   667→		// Skip .entire directory
   668→		if paths.IsInfrastructurePath(file) {
   669→			continue
   670→		}
   671→
   672→		// Skip untracked files
   673→		if st.Worktree == git.Untracked {
   674→			continue
   675→		}
   676→
   677→		var change fileChange
   678→		change.filename = file
   679→
   680→		switch {
   681→		case st.Staging == git.Added || st.Worktree == git.Added:
   682→			change.status = "added"
   683→			// New file - count all lines as added
   684→			absPath := filepath.Join(repoRoot, file)
   685→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   686→				change.added = countLines(content)
   687→			}
   688→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   689→			change.status = "deleted"
   690→			// Deleted file - count lines from HEAD as removed
   691→			if entry, err := headTree.File(file); err == nil {
   692→				if content, err := entry.Contents(); err == nil {
   693→					change.removed = countLines([]byte(content))
   694→				}
   695→			}
   696→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   697→			change.status = "modified"
   698→			// Modified file - compute diff stats
   699→			var headContent, workContent []byte
   700→			if entry, err := headTree.File(file); err == nil {
   701→				if content, err := entry.Contents(); err == nil {
   702→					headContent = []byte(content)
   703→				}
   704→			}
   705→			absPath := filepath.Join(repoRoot, file)
   706→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   707→				workContent = content
   708→			}
   709→			if headContent != nil && workContent != nil {
   710→				change.added, change.removed = computeDiffStats(headContent, workContent)
   711→			}
   712→		default:
   713→			continue
   714→		}
   715→
   716→		changes = append(changes, change)
   717→	}
   718→
   719→	if len(changes) == 0 {
   720→		return true, "", nil
   721→	}
   722→
   723→	// Sort changes by filename for consistent output
   724→	sort.Slice(changes, func(i, j int) bool {
   725→		return changes[i].filename < changes[j].filename
   726→	})
   727→
   728→	var msg strings.Builder
   729→	msg.WriteString("The following uncommitted changes will be reverted:\n")
   730→
   731→	totalAdded, totalRemoved := 0, 0
   732→	for _, c := range changes {
   733→		totalAdded += c.added
   734→		totalRemoved += c.removed
   735→
   736→		var stats string
   737→		switch {
   738→		case c.added > 0 && c.removed > 0:
   739→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
   740→		case c.added > 0:
   741→			stats = fmt.Sprintf("+%d", c.added)
   742→		case c.removed > 0:
   743→			stats = fmt.Sprintf("-%d", c.removed)
   744→		}
   745→
   746→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
   747→		if stats != "" {
   748→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
   749→		}
   750→		msg.WriteString("\n")
   751→	}
   752→
   753→	if totalAdded > 0 || totalRemoved > 0 {
   754→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
   755→	}
   756→
   757→	return true, msg.String(), nil
   758→}
