   760→// countLines counts the number of lines in content.
   761→func countLines(content []byte) int {
   762→	if len(content) == 0 {
   763→		return 0
   764→	}
   765→	count := 1
   766→	for _, b := range content {
   767→		if b == '\n' {
   768→			count++
   769→		}
   770→	}
   771→	// Don't count trailing newline as extra line
   772→	if len(content) > 0 && content[len(content)-1] == '\n' {
   773→		count--
   774→	}
   775→	return count
   776→}
   777→
   778→// computeDiffStats computes added and removed line counts between old and new content.
   779→// Uses a simple line-based diff algorithm.
   780→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
   781→	oldLines := splitLines(oldContent)
   782→	newLines := splitLines(newContent)
   783→
   784→	// Build a set of old lines with counts
   785→	oldSet := make(map[string]int)
   786→	for _, line := range oldLines {
   787→		oldSet[line]++
   788→	}
   789→
   790→	// Check which new lines are truly new
   791→	for _, line := range newLines {
   792→		if oldSet[line] > 0 {
   793→			oldSet[line]--
   794→		} else {
   795→			added++
   796→		}
   797→	}
   798→
   799→	// Remaining old lines are removed
   800→	for _, count := range oldSet {
   801→		removed += count
   802→	}
   803→
   804→	return added, removed
   805→}
   806→
   807→// splitLines splits content into lines, preserving empty lines.
   808→func splitLines(content []byte) []string {
   809→	if len(content) == 0 {
   810→		return nil
   811→	}
   812→	s := string(content)
   813→	// Remove trailing newline to avoid empty last element
   814→	s = strings.TrimSuffix(s, "\n")
   815→	return strings.Split(s, "\n")
   816→}
   817→
   818→// fileExists checks if a file exists at the given path.
   819→func fileExists(path string) bool {
   820→	_, err := os.Stat(path)
   821→	return err == nil
   822→}
