   824→// StageFilesContext describes what type of staging operation this is (for messages).
   825→type StageFilesContext string
   826→
   827→const (
   828→	// StageForSession is used when staging files for a session checkpoint.
   829→	StageForSession StageFilesContext = "session"
   830→	// StageForTask is used when staging files for a task checkpoint.
   831→	StageForTask StageFilesContext = "task"
   832→)
   833→
   834→// StageFiles stages modified, new, and deleted files to the git worktree.
   835→//
   836→// This function handles three categories of file changes:
   837→//  1. Modified files: existing files that have been changed
   838→//  2. New files: files that were created during the session
   839→//  3. Deleted files: files that were removed during the session
   840→//
   841→// Error Handling Strategy:
   842→//   - Individual file staging errors are logged to stderr but don't fail the operation
   843→//   - This ensures that partial staging succeeds even if some files have issues
   844→//   - If a modified file no longer exists, it's treated as a deletion
   845→//
   846→// The stageCtx parameter is used for user-facing messages to indicate whether
   847→// this is staging for a session checkpoint or a task checkpoint.
   848→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
   849→	// Get repo root for resolving file paths
   850→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
   851→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
   852→	// fileExists() could return false for existing files, causing worktree.Remove()
   853→	// to incorrectly delete them.
   854→	repoRoot := worktree.Filesystem.Root()
   855→
   856→	// Stage modified files
   857→	for _, file := range modified {
   858→		// Resolve path relative to repo root for existence check
   859→		absPath := filepath.Join(repoRoot, file)
   860→		if fileExists(absPath) {
   861→			if _, err := worktree.Add(file); err != nil {
   862→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   863→			} else {
   864→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
   865→			}
   866→		} else {
   867→			// File was deleted - stage the deletion
   868→			if _, err := worktree.Remove(file); err != nil {
   869→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
   870→			}
   871→		}
   872→	}
   873→
   874→	// Stage new files
   875→	if len(newFiles) > 0 {
   876→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
   877→		for _, file := range newFiles {
   878→			if _, err := worktree.Add(file); err != nil {
   879→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
   880→			} else {
   881→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
   882→			}
   883→		}
   884→	}
   885→
   886→	// Stage deleted files
   887→	for _, file := range deleted {
   888→		if _, err := worktree.Remove(file); err != nil {
   889→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
   890→		} else {
   891→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
   892→		}
   893→	}
   894→}
