  1005→// collectUntrackedFiles collects all untracked files in the working directory.
  1006→// This is used to capture the initial state when starting a session,
  1007→// ensuring untracked files present at session start are preserved during rewind.
  1008→// Excludes .git/, .entire/, and .claude/ directories (which are system/config directories).
  1009→// Works correctly from any subdirectory within the repository.
  1010→func collectUntrackedFiles() ([]string, error) {
  1011→	// Get repository root to walk from there
  1012→	repoRoot, err := GetWorktreePath()
  1013→	if err != nil {
  1014→		repoRoot = "." // Fallback to current directory
  1015→	}
  1016→
  1017→	var untrackedFiles []string
  1018→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
  1019→		if walkErr != nil {
  1020→			return nil //nolint:nilerr // Skip filesystem errors during walk
  1021→		}
  1022→
  1023→		// Get path relative to repo root
  1024→		relPath, err := filepath.Rel(repoRoot, path)
  1025→		if err != nil {
  1026→			return nil //nolint:nilerr // Skip paths we can't make relative
  1027→		}
  1028→
  1029→		// Skip directories
  1030→		if info.IsDir() {
  1031→			// Skip .git, .claude, and .entire directories
  1032→			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
  1033→				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1034→				return filepath.SkipDir
  1035→			}
  1036→			return nil
  1037→		}
  1038→
  1039→		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
  1040→		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1041→			return nil
  1042→		}
  1043→
  1044→		untrackedFiles = append(untrackedFiles, relPath)
  1045→		return nil
  1046→	})
  1047→	if err != nil {
  1048→		return nil, fmt.Errorf("failed to walk directory: %w", err)
  1049→	}
  1050→
  1051→	return untrackedFiles, nil
  1052→}
