  1115→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1116→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1117→//
  1118→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1119→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1120→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
  1121→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1122→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1123→	// Helper to read first line from a file in tree
  1124→	readFirstLine := func(path string) string {
  1125→		file, err := tree.File(path)
  1126→		if err != nil {
  1127→			return ""
  1128→		}
  1129→		content, err := file.Contents()
  1130→		if err != nil {
  1131→			return ""
  1132→		}
  1133→		lines := strings.SplitN(content, "\n", 2)
  1134→		if len(lines) > 0 && lines[0] != "" {
  1135→			desc := strings.TrimSpace(lines[0])
  1136→			// Remove markdown header prefix if present
  1137→			return strings.TrimPrefix(desc, "# ")
  1138→		}
  1139→		return ""
  1140→	}
  1141→
  1142→	// If metadataDir is provided, look there directly
  1143→	if metadataDir != "" {
  1144→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1145→			return desc
  1146→		}
  1147→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1148→			return desc
  1149→		}
  1150→		return NoDescription
  1151→	}
  1152→
  1153→	// No metadataDir provided - first try looking at the root of the tree
  1154→	// (used when the tree is already the session directory)
  1155→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1156→		return desc
  1157→	}
  1158→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1159→		return desc
  1160→	}
  1161→
  1162→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1163→	// (used when the tree is the full worktree)
  1164→	var desc string
  1165→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1166→	_ = tree.Files().ForEach(func(f *object.File) error {
  1167→		if desc != "" {
  1168→			return nil // Already found description
  1169→		}
  1170→		name := f.Name
  1171→		if strings.Contains(name, ".entire/metadata/") {
  1172→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1173→				content, err := f.Contents()
  1174→				if err != nil {
  1175→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1176→				}
  1177→				lines := strings.SplitN(content, "\n", 2)
  1178→				if len(lines) > 0 && lines[0] != "" {
  1179→					desc = strings.TrimSpace(lines[0])
  1180→					desc = strings.TrimPrefix(desc, "# ")
  1181→				}
  1182→			}
  1183→		}
  1184→		return nil
  1185→	})
  1186→
  1187→	if desc != "" {
  1188→		return desc
  1189→	}
  1190→	return NoDescription
  1191→}
