  1193→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1194→// It checks local config first, then falls back to global config.
  1195→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
  1196→// operations to proceed even without git user config, which is especially useful
  1197→// for internal metadata commits on branches like entire/sessions.
  1198→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1199→	// Get repository config (includes local settings)
  1200→	cfg, err := repo.Config()
  1201→	if err == nil {
  1202→		name = cfg.User.Name
  1203→		email = cfg.User.Email
  1204→	}
  1205→
  1206→	// If not found in local config, try global config
  1207→	if name == "" || email == "" {
  1208→		globalCfg, err := config.LoadConfig(config.GlobalScope)
  1209→		if err == nil {
  1210→			if name == "" {
  1211→				name = globalCfg.User.Name
  1212→			}
  1213→			if email == "" {
  1214→				email = globalCfg.User.Email
  1215→			}
  1216→		}
  1217→	}
  1218→
  1219→	// Provide sensible defaults if git user is not configured
  1220→	if name == "" {
  1221→		name = "Unknown"
  1222→	}
  1223→	if email == "" {
  1224→		email = "unknown@local"
  1225→	}
  1226→
  1227→	return name, email
  1228→}
